//! Actions-only original physical Common READ/consumer -> explicit manual WRITE.
//! Same FD one-byte ciphertext prefix, no-I/O queue, full result/cancel and Join.
//! This does not execute the original SDK/SO or manufacture Hosted/media grants.
use super::*;
use n::im_inbox::{ReadStatusBudget,ReadStatusTargets,ReadStatusAction,ReadStatusWait,ReadStatusPrepared};
use n::im_read_status_policy::NativeReadStatusConfig;
async fn setup(handle:&RuntimeHandle,who:&AttemptOwner,scope:&RpcConnectionScope,temp:&TempDatabase,run:Arc<n::account_runs::RunToken>,parent:Arc<ImReceiptGate>)->(Arc<ReadStatusTargets>,Arc<ReadStatusAction>,Arc<n::im_inbox::ReceivedWritePermit>){setup_with_timeout(handle,who,scope,temp,run,parent,Duration::from_secs(3)).await}
async fn setup_with_timeout(handle:&RuntimeHandle,who:&AttemptOwner,scope:&RpcConnectionScope,temp:&TempDatabase,run:Arc<n::account_runs::RunToken>,parent:Arc<ImReceiptGate>,timeout:Duration)->(Arc<ReadStatusTargets>,Arc<ReadStatusAction>,Arc<n::im_inbox::ReceivedWritePermit>){
    let commands=handle.command_handle();let reply=bounded(commands.read_im(who,scope,refresh(),parent.clone())).await.unwrap();let mut cursor=CursorSession::from_refresh(run.clone(),parent.clone(),&reply).unwrap();cursor.observe_refresh(&temp.database,&reply).unwrap();let plan=cursor.next_gap(&temp.database).unwrap().unwrap();let reply=bounded(commands.read_im(who,scope,plan.query(),parent.clone())).await.unwrap();let span=cursor.commit_gap(&temp.database,&plan,&reply).unwrap();let targets=ReadStatusTargets::original(temp.database.clone(),run.clone(),parent.clone(),ReadStatusBudget::original());targets.observe(&span).unwrap();let view=targets.list().pop().unwrap();let action=ReadStatusAction::original(temp.database.clone(),run,parent,who.clone(),scope.clone(),targets.get(view.id,"1").unwrap(),&"a".repeat(32),Instant::now()+timeout).unwrap();let ReadStatusPrepared::Fresh(permit)=n::im_inbox::begin_read_status(temp.database.clone(),action.clone(),&NativeReadStatusConfig{set_read_status:true}).unwrap()else{panic!("fresh original manual position")};(targets,action,permit)
}
fn manual_state(temp:&TempDatabase)->(i64,Option<i32>){temp.database.with_conn(|c|c.query_row("SELECT state,request_id FROM app_voice_im_read_status_actions",[],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|_|"fixture")).unwrap()}
async fn actual_prefix(parent_retirement:bool,deadline:bool){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let policy=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_reads(&mut peer).await;assert!(peer.next().await.is_none(),"one incomplete original ciphertext prefix is not a complete manual query or replay");}).await});
    let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);let mut connection=connected(&policy,who.clone(),Instant::now()+Duration::from_secs(6)).await;
    // Reuse only the test FD wrapper; this remains the main original Group
    // scope, not an auxiliary/UserEntry connection or a replacement socket.
    let prefix=n::router_runtime::tests::auxiliary_io::AuxiliaryIoTest::original_unarmed(1);n::common_runtime::tests::gate_auxiliary_prefix(connection.common.as_mut().unwrap(),prefix.clone());let scope=connection.connection_scope();assert!(prefix.scope().matches(&scope));let(mut handle,mut events)=connection.attach().unwrap();auth(&handle,&mut events,&who,&scope,true).await;let parent=ImReceiptGate::fresh();let(targets,action,permit)=setup_with_timeout(&handle,&who,&scope,&temp,run,parent.clone(),Duration::from_secs(if deadline{1}else{3})).await;prefix.arm();let commands=handle.command_handle();let mut sending=Box::pin(commands.write_received(&who,&scope,permit.clone()));
    tokio::select!{result=sending.as_mut()=>panic!("partial original WRITE cannot complete: {result:?}"),_=bounded(prefix.paused())=>{}}
    assert_eq!(prefix.accepted.load(Ordering::SeqCst),1);assert!(!prefix.dropped.load(Ordering::SeqCst));assert_eq!(manual_state(&temp),(0,Some(4)));assert_eq!(state(&temp),(0,Some(4)));assert!(!permit.has_submitted());
    let reason=if deadline{assert_eq!(bounded(sending).await.err(),Some(RuntimeError::Timeout));RuntimeError::Timeout}else if parent_retirement{parent.retire();assert_eq!(bounded(sending).await.err(),Some(RuntimeError::Cancelled));RuntimeError::Cancelled}else{drop(ReadStatusWait::original(action.clone()));drop(sending);RuntimeError::Cancelled};
    bounded(scope.closed()).await;let closed=bounded(handle.close()).await;assert!(closed.io_released());assert_eq!(closed.reason,reason);assert!(prefix.dropped.load(Ordering::SeqCst),"FD Drop precedes terminal ownership report");assert_eq!(manual_state(&temp),(0,Some(4)));assert_eq!(state(&temp),(0,Some(4)));assert_eq!(scope.native_rpc_resources(),(0,0));targets.clear();drop(permit);drop(action);assert_eq!(targets.target_resources(),(0,0));bounded(serving).await.unwrap();
}
#[tokio::test]async fn manual_read_status_io_actual_one_byte_partial_cancel_keeps_unknown_and_same_fd_join(){Box::pin(actual_prefix(false,false)).await;}
#[tokio::test]async fn manual_read_status_io_parent_retirement_after_one_original_byte_has_no_late_frame_or_refund(){Box::pin(actual_prefix(true,false)).await;}
#[tokio::test]async fn manual_read_status_io_original_action_deadline_bounds_actual_partial_write_before_actor_budget(){Box::pin(actual_prefix(false,true)).await;}
#[tokio::test]async fn manual_read_status_io_queued_action_retirement_sends_no_write_id_and_preserves_original_logout(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let policy=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_reads(&mut peer).await;let packet=peer.next().await.unwrap();let request=decode_request(&packet[1..]).unwrap();assert_eq!(request.call_id,4,"queued manual request never consumed an ID");assert_eq!(request.method,n::rpc_logout::LOGOUT_SESSION_METHOD.as_bytes());peer.send(&[reply(request.call_id,&[0,1,0,0,0,0])]).await;assert!(peer.next().await.is_none());}).await});
    let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);let connection=connected(&policy,who.clone(),Instant::now()+Duration::from_secs(6)).await;let scope=connection.connection_scope();let(mut handle,mut events)=connection.attach().unwrap();auth(&handle,&mut events,&who,&scope,true).await;let(_targets,action,permit)=setup(&handle,&who,&scope,&temp,run,ImReceiptGate::fresh()).await;
    let(reply,data)=oneshot::channel();let receipt=handle.command_handle().enqueue(&who,&scope,Operation::WriteReceived(Box::new(ReceivedWork{permit:permit.clone(),reply}))).unwrap();drop(data);action.cancel();assert_eq!(bounded(receipt).await.unwrap().err(),Some(RuntimeError::Scope));assert_eq!(manual_state(&temp),(3,None));assert_eq!(state(&temp),(3,None));assert!(scope.is_open());let closed=bounded(handle.logout(&who,&scope,&[])).await.unwrap();assert!(closed.io_released());assert_eq!(scope.native_rpc_resources(),(0,0));bounded(serving).await.unwrap();
}).await;}
async fn full_submission(sql_failure:bool){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let policy=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let(seen,submitted)=oneshot::channel();let(release,reply_ready)=oneshot::channel();let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_reads(&mut peer).await;let packet=peer.next().await.unwrap();assert_eq!(query(&packet,n::im_data::SET_READ_METHOD),4);seen.send(()).unwrap();if reply_ready.await.is_ok(){peer.send(&[reply(4,&[0,1,0,0,0,0])]).await;}assert!(peer.next().await.is_none(),"original unknown full WRITE cannot replay or use a readonly cancellation rule");}).await});
    let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);let connection=connected(&policy,who.clone(),Instant::now()+Duration::from_secs(6)).await;let scope=connection.connection_scope();let(mut handle,mut events)=connection.attach().unwrap();auth(&handle,&mut events,&who,&scope,true).await;let(targets,action,permit)=setup(&handle,&who,&scope,&temp,run,ImReceiptGate::fresh()).await;let commands=handle.command_handle();let mut writing=Box::pin(commands.write_received(&who,&scope,permit.clone()));tokio::select!{result=writing.as_mut()=>panic!("no original reply yet: {result:?}"),_=bounded(submitted)=>{}}
    tokio::select!{result=writing.as_mut()=>panic!("original private result is absent: {result:?}"),_=bounded(async{while !permit.has_submitted(){tokio::task::yield_now().await;}})=>{}}
    assert_eq!(manual_state(&temp),(0,Some(4)));let reason=if sql_failure{temp.database.with_conn(|c|c.execute_batch("CREATE TRIGGER reject_manual_result BEFORE UPDATE OF state ON app_voice_im_read_status_actions WHEN NEW.state IN(1,2) BEGIN SELECT RAISE(ABORT,'fixture'); END").map_err(|_|"fixture")).unwrap();release.send(()).unwrap();assert_eq!(bounded(writing).await.err(),Some(RuntimeError::Protocol));RuntimeError::Protocol}else{drop(release);drop(writing);action.cancel();RuntimeError::Cancelled};bounded(scope.closed()).await;let closed=bounded(handle.close()).await;assert!(closed.io_released());assert_eq!(closed.reason,reason);assert_eq!(manual_state(&temp),(0,Some(4)));assert_eq!(state(&temp),(0,Some(4)));assert_eq!(scope.native_rpc_resources(),(0,0));targets.clear();drop(permit);drop(action);assert_eq!(targets.target_resources(),(0,0));bounded(serving).await.unwrap();
}
#[tokio::test]async fn manual_read_status_io_full_wait_drop_keeps_both_unknown_and_joins_original_stream(){Box::pin(full_submission(false)).await;}
#[tokio::test]async fn manual_read_status_io_matched_reply_manual_sql_failure_rolls_back_both_and_joins_original_stream(){Box::pin(full_submission(true)).await;}
